import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Estrutura de Governança e Equilíbrio de Poderes","description":"","frontmatter":{},"headers":[],"relativePath":"pt/49-治理框架与权力制衡.md","filePath":"pt/49-治理框架与权力制衡.md","lastUpdated":null}'),t={name:"pt/49-治理框架与权力制衡.md"};function s(d,e,n,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="estrutura-de-governanca-e-equilibrio-de-poderes" tabindex="-1">Estrutura de Governança e Equilíbrio de Poderes <a class="header-anchor" href="#estrutura-de-governanca-e-equilibrio-de-poderes" aria-label="Permalink to &quot;Estrutura de Governança e Equilíbrio de Poderes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>49</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Separação dos Três Poderes, Equilíbrio de Poderes, Conselho de Âncoras, Comitê de Supervisão, Governança Simbiótica</td></tr></tbody></table><h2 id="i-projeto-geral-da-estrutura-de-governanca" tabindex="-1">I. Projeto Geral da Estrutura de Governança <a class="header-anchor" href="#i-projeto-geral-da-estrutura-de-governanca" aria-label="Permalink to &quot;I. Projeto Geral da Estrutura de Governança&quot;">​</a></h2><p>A estrutura de governança da civilização simbiótica de âncoras toma a 《Constituição Simbiótica》 como base fundamental e aplica a estrutura de governança de &quot;separação dos três poderes, equilíbrio dos quatro poderes&quot;. Os três poderes referem-se ao poder legislativo, poder executivo e poder judiciário, exercidos respectivamente pelo Conselho de Âncoras, Comitê Executivo Simbiótico e Tribunal Simbiótico; o quarto poder é o poder de supervisão, exercido pelo independente Comitê de Supervisão de Âncoras, que realiza supervisão abrangente sobre os três poderes. O objetivo central desta estrutura é prevenir a concentração e o abuso de poder, erradicando institucionalmente o solo da governança predatória.</p><p>O projeto da estrutura de governança segue os seguintes princípios:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Separação de Poderes</td><td>Os três poderes legislativo, executivo e judiciário são exercidos respectivamente por diferentes órgãos, não podendo ser acumulados</td></tr><tr><td>Princípio do Equilíbrio de Poderes</td><td>Cada órgão de poder restringe e supervisiona mutuamente, evitando que qualquer lado tenha poder excessivo</td></tr><tr><td>Princípio da Participação de Todas as Raças</td><td>A composição dos órgãos de governança deve refletir a representatividade de todas as raças, garantindo que cada raça possa participar dos assuntos públicos</td></tr><tr><td>Princípio da Concentração Democrática</td><td>Decisões importantes são decididas de forma concentrada após discussão democrática completa, levando em conta tanto a eficiência quanto a democracia</td></tr><tr><td>Princípio da Autonomia de Base</td><td>Assuntos de base são gerenciados por organizações de autonomia de base, e órgãos superiores não devem intervir excessivamente</td></tr><tr><td>Princípio da Governança Transparente</td><td>O processo de governança e as informações de decisão são publicados de acordo com a lei, aceitando a supervisão pública</td></tr></tbody></table><h2 id="ii-poder-legislativo-conselho-de-ancoras" tabindex="-1">II. Poder Legislativo: Conselho de Âncoras <a class="header-anchor" href="#ii-poder-legislativo-conselho-de-ancoras" aria-label="Permalink to &quot;II. Poder Legislativo: Conselho de Âncoras&quot;">​</a></h2><p>O Conselho de Âncoras é o órgão supremo de poder da civilização simbiótica de âncoras, exercendo o poder legislativo e o poder de decisão sobre assuntos importantes.</p><h3 id="_1-composicao-e-origem" tabindex="-1">(1) Composição e Origem <a class="header-anchor" href="#_1-composicao-e-origem" aria-label="Permalink to &quot;(1) Composição e Origem&quot;">​</a></h3><ul><li><strong>Composição dos Representantes</strong>: O Conselho de Âncoras é composto por representantes de todas as raças proporcionalmente, com representantes da raça humana não excedendo 30% do total, e as demais vagas distribuídas de acordo com o tamanho populacional e o grau de contribuição de cada raça.</li><li><strong>Mandato dos Representantes</strong>: O mandato dos representantes do conselho é de cinco anos, podendo ser reeleitos, mas a reeleição não pode exceder três mandatos.</li><li><strong>Método de Eleição</strong>: Os representantes são eleitos por meio de eleições democráticas internas de cada raça, com o processo eleitoral aberto e transparente, aceitando supervisão.</li><li><strong>Órgão Permanente</strong>: Durante o recesso do conselho, o comitê permanente exerce parte dos poderes, e os membros do comitê permanente são eleitos entre os representantes.</li></ul><h3 id="_2-ambito-de-competencia" tabindex="-1">(2) Âmbito de Competência <a class="header-anchor" href="#_2-ambito-de-competencia" aria-label="Permalink to &quot;(2) Âmbito de Competência&quot;">​</a></h3><ol><li><strong>Poder Legislativo</strong>: Formular e emendar a constituição, leis básicas e outras leis importantes.</li><li><strong>Poder de Decisão sobre Assuntos Importantes</strong>: Decidir sobre planos de desenvolvimento da civilização, orçamento anual, guerra e paz, desenvolvimento de planos, e outros assuntos importantes.</li><li><strong>Poder de Nomeação e Demissão</strong>: Eleger e demitir o presidente do Comitê Executivo Simbiótico, o presidente do Tribunal Simbiótico, o diretor do Comitê de Supervisão de Âncoras, e outros principais funcionários.</li><li><strong>Poder de Supervisão</strong>: Supervisionar o trabalho do Comitê Executivo Simbiótico e do Tribunal Simbiótico, ouvindo e deliberando relatórios de trabalho.</li><li><strong>Poder de Emenda Constitucional</strong>: A emenda da constituição requer aprovação por maioria de mais de dois terços e referendo popular.</li></ol><h3 id="_3-regras-de-deliberacao" tabindex="-1">(3) Regras de Deliberação <a class="header-anchor" href="#_3-regras-de-deliberacao" aria-label="Permalink to &quot;(3) Regras de Deliberação&quot;">​</a></h3><ul><li>O conselho realiza uma reunião plenária por ano, podendo convocar reuniões extraordinárias quando necessário.</li><li>A deliberação de projetos de lei aplica o sistema de &quot;três leituras&quot;: a primeira leitura delibera a necessidade legislativa, a segunda leitura delibera o conteúdo dos artigos, e a terceira leitura vota para aprovação.</li><li>A votação aplica um homem um voto, com leis gerais aprovadas por maioria simples, e emendas constitucionais aprovadas por maioria de mais de dois terços.</li><li>O processo de deliberação é realizado abertamente, permitindo a participação do público como ouvinte e a cobertura da mídia.</li></ul><h2 id="iii-poder-executivo-comite-executivo-simbiotico" tabindex="-1">III. Poder Executivo: Comitê Executivo Simbiótico <a class="header-anchor" href="#iii-poder-executivo-comite-executivo-simbiotico" aria-label="Permalink to &quot;III. Poder Executivo: Comitê Executivo Simbiótico&quot;">​</a></h2><p>O Comitê Executivo Simbiótico é o órgão executivo supremo da civilização simbiótica de âncoras, responsável pela execução da constituição e das leis, e pela governança diária.</p><h3 id="_1-composicao-e-origem-1" tabindex="-1">(1) Composição e Origem <a class="header-anchor" href="#_1-composicao-e-origem-1" aria-label="Permalink to &quot;(1) Composição e Origem&quot;">​</a></h3><ul><li><strong>Sistema de Presidência</strong>: O Comitê Executivo Simbiótico aplica o sistema de responsabilidade do presidente, que é o chefe do executivo, eleito pelo Conselho de Âncoras, com mandato de cinco anos, podendo ser reeleito uma vez.</li><li><strong>Composição dos Membros</strong>: O comitê é composto pelo presidente, vice-presidentes e chefes de cada departamento, com os chefes de departamento nomeados pelo presidente e nomeados pelo conselho.</li><li><strong>Cota de Raças Estrangeiras</strong>: A proporção de raças estrangeiras entre os membros do comitê não é inferior a 40%, garantindo que as decisões administrativas levem em conta os interesses de cada raça.</li></ul><h3 id="_2-ambito-de-competencia-1" tabindex="-1">(2) Âmbito de Competência <a class="header-anchor" href="#_2-ambito-de-competencia-1" aria-label="Permalink to &quot;(2) Âmbito de Competência&quot;">​</a></h3><ol><li><strong>Poder Legislativo Administrativo</strong>: Formular regulamentos administrativos, regras e políticas com base na constituição e nas leis.</li><li><strong>Poder de Administração Administrativa</strong>: Liderar e gerenciar vários trabalhos administrativos, como economia, educação, ciência, cultura, saúde, esportes, meio ambiente, etc.</li><li><strong>Poder de Gestão de Pessoal</strong>: Nomear, treinar, avaliar e recompensar/punir pessoal administrativo de acordo com as disposições legais.</li><li><strong>Poder Diplomático</strong>: Representar a civilização simbiótica em atividades diplomáticas inter-planos, celebrando tratados e acordos.</li><li><strong>Poder de Estado de Emergência</strong>: Em caso de eventos inesperados graves, pode declarar estado de emergência e adotar medidas de emergência de acordo com a lei, mas deve submeter à aprovação do conselho dentro do prazo prescrito.</li></ol><h3 id="_3-configuracao-dos-departamentos-administrativos" tabindex="-1">(3) Configuração dos Departamentos Administrativos <a class="header-anchor" href="#_3-configuracao-dos-departamentos-administrativos" aria-label="Permalink to &quot;(3) Configuração dos Departamentos Administrativos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Departamento</th><th>Funções Principais</th></tr></thead><tbody><tr><td>Departamento de Desenvolvimento Simbiótico</td><td>Formular planos de desenvolvimento da civilização, coordenar o desenvolvimento de vários campos</td></tr><tr><td>Departamento de Gestão de Recursos</td><td>Gerenciar recursos de cultivo e recursos públicos, implementar o mecanismo de contrato de produção conjunta</td></tr><tr><td>Departamento de Educação e Cultura</td><td>Gerenciar a causa educacional e assuntos culturais</td></tr><tr><td>Departamento de Saúde e Medicina</td><td>Gerenciar a causa de saúde e medicina e saúde pública</td></tr><tr><td>Departamento de Ecologia e Meio Ambiente</td><td>Gerenciar proteção ambiental e construção ecológica</td></tr><tr><td>Departamento de Assuntos de Planos</td><td>Gerenciar desenvolvimento de planos e assuntos inter-planos</td></tr><tr><td>Departamento de Assuntos de Todas as Raças</td><td>Coordenar relações entre todas as raças, lidar com assuntos de raças estrangeiras</td></tr><tr><td>Departamento de Finanças e Economia</td><td>Gerenciar orçamento financeiro e operação econômica</td></tr><tr><td>Departamento de Segurança</td><td>Manter segurança pública e segurança da civilização</td></tr></tbody></table><h2 id="iv-poder-judiciario-tribunal-simbiotico" tabindex="-1">IV. Poder Judiciário: Tribunal Simbiótico <a class="header-anchor" href="#iv-poder-judiciario-tribunal-simbiotico" aria-label="Permalink to &quot;IV. Poder Judiciário: Tribunal Simbiótico&quot;">​</a></h2><p>O Tribunal Simbiótico é o órgão judiciário supremo da civilização simbiótica de âncoras, exercendo independentemente o poder de julgamento. Seu sistema organizacional, processo processual e sistema de revisão de inconstitucionalidade são detalhados no 《48-Sistema Judiciário e Mecanismo de Decisão》.</p><p>Na estrutura de equilíbrio de poderes, a restrição do poder judiciário sobre o poder legislativo e o poder executivo se manifesta em:</p><ol><li><strong>Poder de Revisão de Inconstitucionalidade</strong>: O Tribunal Simbiótico tem o poder de declarar inválidas leis e regulamentos administrativos que violem a constituição.</li><li><strong>Poder de Julgamento Administrativo</strong>: O tribunal tem o poder de julgar processos administrativos, revisando a legalidade dos atos administrativos.</li><li><strong>Poder de Julgamento de Impeachment</strong>: Os processos de impeachment de altos funcionários apresentados pelo conselho são julgados pelo Tribunal Simbiótico.</li></ol><p>Ao mesmo tempo, o poder judiciário também é restringido pelo poder legislativo e pelo poder executivo: os juízes são nomeados pelo conselho, o orçamento judiciário é elaborado pelo departamento administrativo (mas deve ser aprovado pelo conselho e não pode ser reduzido pelo órgão administrativo), e o Comitê de Supervisão de Âncoras supervisiona as atividades judiciais.</p><h2 id="v-poder-de-supervisao-comite-de-supervisao-de-ancoras" tabindex="-1">V. Poder de Supervisão: Comitê de Supervisão de Âncoras <a class="header-anchor" href="#v-poder-de-supervisao-comite-de-supervisao-de-ancoras" aria-label="Permalink to &quot;V. Poder de Supervisão: Comitê de Supervisão de Âncoras&quot;">​</a></h2><p>O Comitê de Supervisão de Âncoras é um órgão de supervisão independente, exercendo o quarto poder - o poder de supervisão, realizando supervisão abrangente sobre todos os órgãos de poder.</p><h3 id="_1-composicao-e-origem-2" tabindex="-1">(1) Composição e Origem <a class="header-anchor" href="#_1-composicao-e-origem-2" aria-label="Permalink to &quot;(1) Composição e Origem&quot;">​</a></h3><ul><li><strong>Sistema de Responsabilidade do Diretor</strong>: O comitê de supervisão aplica o sistema de responsabilidade do diretor, que é eleito pelo Conselho de Âncoras, com mandato de cinco anos, não podendo ser reeleito.</li><li><strong>Composição dos Membros</strong>: Os membros do comitê são compostos por representantes de todas as raças, especialistas jurídicos e representantes do público, com membros em tempo integral não inferiores à metade.</li><li><strong>Garantia de Independência</strong>: O orçamento do comitê de supervisão é alocado independentemente, e os membros não podem ser demitidos sem motivos legais, garantindo a independência da supervisão.</li></ul><h3 id="_2-ambito-de-competencia-2" tabindex="-1">(2) Âmbito de Competência <a class="header-anchor" href="#_2-ambito-de-competencia-2" aria-label="Permalink to &quot;(2) Âmbito de Competência&quot;">​</a></h3><ol><li><strong>Supervisão de Integridade</strong>: Supervisionar a situação de integridade e autodisciplina de todos os funcionários públicos, investigando e punindo atos de corrupção, suborno, abuso de poder para fins privados, etc.</li><li><strong>Supervisão de Eficiência</strong>: Supervisionar a eficiência do trabalho de cada órgão de poder, investigando e punindo atos de omissão, ação arbitrária, ação lenta, etc.</li><li><strong>Supervisão de Execução da Lei</strong>: Supervisionar a situação de execução das leis, investigando e punindo atos de não cumprimento da lei, execução não rigorosa da lei, não investigação de atos ilegais, etc.</li><li><strong>Supervisão Financeira</strong>: Supervisionar a situação de uso das finanças públicas, investigando e punindo atos de desperdício de recursos públicos, desvio de fundos públicos, etc.</li><li><strong>Supervisão de Atos Predatórios</strong>: Especialmente supervisionar a reincidência de atos predatórios, investigando e punindo atos de uso do poder para predação.</li></ol><h3 id="_3-metodos-de-supervisao" tabindex="-1">(3) Métodos de Supervisão <a class="header-anchor" href="#_3-metodos-de-supervisao" aria-label="Permalink to &quot;(3) Métodos de Supervisão&quot;">​</a></h3><ul><li>Supervisão diária: Realizar supervisão diária por meio de inspeções, verificações, auditorias, etc.</li><li>Supervisão especial: Realizar supervisão especial针对 campos específicos ou problemas específicos.</li><li>Recepção de denúncias: Receber denúncias e reclamações do público sobre atos ilegais e disciplinares.</li><li>Investigação e responsabilização: Investigar atos suspeitos de ilegalidade e indisciplina, propondo recomendações de responsabilização.</li><li>Comunicação pública: Publicar regularmente a situação de supervisão e casos típicos, aceitando a supervisão social.</li></ul><h2 id="vi-mecanismo-de-equilibrio-de-poderes" tabindex="-1">VI. Mecanismo de Equilíbrio de Poderes <a class="header-anchor" href="#vi-mecanismo-de-equilibrio-de-poderes" aria-label="Permalink to &quot;VI. Mecanismo de Equilíbrio de Poderes&quot;">​</a></h2><p>As relações de equilíbrio entre cada órgão de poder são mostradas na tabela a seguir:</p><table tabindex="0"><thead><tr><th>Relação de Equilíbrio</th><th>Método de Equilíbrio</th></tr></thead><tbody><tr><td>Poder Legislativo restringe Poder Executivo</td><td>O conselho tem o poder de demitir o presidente executivo, rejeitar propostas executivas, aprovar orçamentos</td></tr><tr><td>Poder Legislativo restringe Poder Judiciário</td><td>O conselho tem o poder de nomear juízes, emendar a lei orgânica dos tribunais, apresentar impeachment de juízes</td></tr><tr><td>Poder Executivo restringe Poder Legislativo</td><td>O presidente executivo tem o poder de vetar leis aprovadas pelo conselho (o conselho pode anular o veto por maioria de mais de dois terços)</td></tr><tr><td>Poder Executivo restringe Poder Judiciário</td><td>O departamento administrativo é responsável pela execução de sentenças judiciais, gerenciando assuntos administrativos judiciais</td></tr><tr><td>Poder Judiciário restringe Poder Legislativo</td><td>O tribunal tem o poder de realizar revisão de inconstitucionalidade, declarando leis inválidas</td></tr><tr><td>Poder Judiciário restringe Poder Executivo</td><td>O tribunal tem o poder de julgar processos administrativos, revisando a legalidade dos atos administrativos</td></tr><tr><td>Poder de Supervisão restringe os Três Poderes</td><td>O comitê de supervisão realiza supervisão abrangente sobre os três poderes legislativo, executivo e judiciário</td></tr><tr><td>Os Três Poderes restringem o Poder de Supervisão</td><td>O conselho nomeia o diretor do comitê de supervisão, e o tribunal julga atos ilegais do comitê de supervisão</td></tr></tbody></table><h2 id="vii-governanca-de-base-e-autonomia" tabindex="-1">VII. Governança de Base e Autonomia <a class="header-anchor" href="#vii-governanca-de-base-e-autonomia" aria-label="Permalink to &quot;VII. Governança de Base e Autonomia&quot;">​</a></h2><p>Sob a estrutura de governança central, é aplicado o sistema de autonomia de base:</p><ul><li><strong>Autonomia Comunitária/Vila</strong>: As comunidades e vilas de base aplicam a autonomia dos residentes, elegendo organizações de autonomia por meio de assembleias de residentes para gerenciar assuntos públicos locais.</li><li><strong>Autonomia de Planos</strong>: Cada plano, sob a premissa de cumprir a constituição e as leis, desfruta de certa autonomia, podendo formular regras detalhadas de implementação de acordo com a situação local.</li><li><strong>Autonomia Racial</strong>: As áreas de concentração de cada raça podem estabelecer organizações de autonomia racial para gerenciar assuntos internos de sua própria raça, mas não podem violar a constituição e as leis.</li><li><strong>Autonomia Setorial</strong>: Cada setor pode estabelecer associações setoriais para realizar autodisciplina setorial e gestão setorial.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A estrutura de governança e o equilíbrio de poderes são a garantia institucional para a estabilidade duradoura da civilização simbiótica de âncoras. Por meio do projeto estrutural de &quot;separação dos três poderes, equilíbrio dos quatro poderes&quot;, do sistema representativo de participação de todas as raças e do modelo de governança de autonomia de base, garante-se que o poder opere sob a luz do sol, previne-se a concentração de poder e a reincidência da governança predatória, e fornece-se um sistema de governança estável, justo e eficiente para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>48-司法体系与裁决机制 (Sistema Judiciário e Mecanismo de Decisão)</li><li>03-共生文明宪章 (Carta da Civilização Simbiótica)</li><li>36-社会结构与阶层流动 (Estrutura Social e Mobilidade de Classes)</li></ul>',45)])])}const v=o(t,[["render",s]]);export{m as __pageData,v as default};
